### Design your prompt here
def restaurant_data_structure_prompt_generation(restaurant_paragraph):
    base_system_msg = """
    You are a professional data extraction expert.
    You ONLY output valid JSON, no extra text.
    Extract restaurant information strictly follow the JSON schema.
    """

    base_user_prompt = f"""
    Task: Extract restaurant information into valid JSON format.
    Do NOT add any explanation, only JSON.

    Restaurant description:
    {restaurant_paragraph}

    Example Output Format:
    {EXAMPLE_OUTPUT}

    Now output JSON only:
    """
    return base_system_msg, base_user_prompt


