# Validation
from pydantic import BaseModel, Field, ValidationError
from typing import List, Optional


### 3.1. Define the schema
class Restaurant(BaseModel):
    name: str
    location: str
    type: str
    food_style: str
    rating: Optional[float] = None
    price_range: Optional[int] = None
    signatures: List[str] = Field(default_factory=list)
    vibe: Optional[str] = None
    environment: str
    shortcomings: List[str] = Field(default_factory=list)


### 3.2. Use the validation method to validate the test_response from the unit test
try:
    restaurant_data = Restaurant.model_validate_json(test_response)
    print(f"✅ 验证成功! 餐厅名: {restaurant_data.name}")
except ValidationError as e:
    print(f"❌ 验证失败: {e.json()}")


def JSON_auto_repair_prompts(candidate_json_output, error_message):
    auto_repair_system_msg = """
    You are a JSON repair expert.
    Fix invalid JSON, output ONLY valid JSON, no extra words.
    """
    auto_repair_prompt = f"""
    Fix this JSON:
    {candidate_json_output}

    Error:
    {error_message}

    Return ONLY valid JSON:
    """
    return auto_repair_system_msg, auto_repair_prompt


### Your Code Here:
structured_restaurant_lists = []
for i, restaurant_paragraph in enumerate(restaurant_list):
    ### 2.1: Produce your initial output
    system_msg, prompt_txt = restaurant_data_structure_prompt_generation(restaurant_paragraph)
    response = safe_llm_call(system_msg, prompt_txt)

    ### 2.2: Validation and Auto Correction loop
    max_retries = 3
    current_retries = 0
    valid = False

    while not valid and current_retries < max_retries:
        try:
            Restaurant.model_validate_json(response)
            valid = True
        except ValidationError as e:
            current_retries += 1
            fix_sys, fix_prompt = JSON_auto_repair_prompts(response, str(e))
            response = safe_llm_call(fix_sys, fix_prompt)

    ### 2.3: Append your finalized response
    structured_restaurant_lists.append(response)

    # A manual progress bar
    if (i + 1) % 20 == 0:
        print(f'{i + 1} / {len(restaurant_list)} 完成')

print('✅ ALL DONE!!')

# 转 JSON 并添加 itemId
structured_restaurant_lists_json = [json.loads(response) for response in structured_restaurant_lists]

for i, item in enumerate(structured_restaurant_lists_json):
    item['itemId'] = 1000001 + i

